  "code": "private List<OraclePackage> getAllRealOraclePackage(OBridgeConfiguration c) {
    String sql = "SELECT object_name FROM user_objects "
        + "WHERE object_type = 'PACKAGE' AND object_name LIKE ?";

    return jdbcTemplate.query(sql, (resultSet, rowNum) -> {
        String name = resultSet.getString("object_name");
        OraclePackage oraclePackage = new OraclePackage();
        oraclePackage.setName(name);
        oraclePackage.setProcedureList(getAllProcedure(name, ""));
        return oraclePackage;
    }, c.getPackagesLike());
}",
  "imports": "import java.util.List;",
  "dependency_notes": "OraclePackage must have an accessible no-argument constructor. The return type of getAllProcedure(String, String) must be accepted by OraclePackage.setProcedureList. The package names of the project types were not supplied.",
  "retrieval_notes": "Implemented using only the supplied specification."
}
